def table(rows,widths):
    a=[[Paragraph(str(c),styles['SmallX']) for c in row] for row in rows]
    t=Table(a,colWidths=widths,hAlign='LEFT',repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e8eff4')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,0),.7,colors.HexColor('#9aacba')),('LINEBELOW',(0,1),(-1,-1),.3,colors.HexColor('#dce3e8'))]))
